// `.routify/` is generated by `routify build` and gitignored (see routify.config.js),
// so its output can never carry its own .d.ts. Router.svelte's `routes` prop is untyped
// (plain `export let routes`), so `unknown` here is enough for App.svelte to satisfy it
// without lying about the route tree's shape.
declare module "*/routes.default.js" {
	export const routes: unknown;
}
